Query: libxml2 xmlXPathNodeEval usage examples - Here is an example of using libxml2's xmlXPathNodeEval function:

```c
#include <stdio.h>
#include <libxml/xpath.h>
#include <libxml/parser.h>

int main() {
    xmlDocPtr doc;
    xmlXPathContextPtr xpathCtx;
    xmlXPathObjectPtr xpathObj;

    // Load XML file
    doc = xmlReadFile("example.xml", NULL, 0);
    if (doc == NULL) {
        fprintf(stderr, "Error: unable to parse file\n");
        return 1;
    }

    // Create XPath evaluation context
    xpathCtx = xmlXPathNewContext(doc);
    if (xpathCtx == NULL) {
        fprintf(stderr, "Error: unable to create new XPath context\n");
        xmlFreeDoc(doc);
        return 1;
    }

    // Evaluate XPath expression
    xpathObj = xmlXPathNodeEval(xmlDocGetRootElement(doc), (const xmlChar*)"//book", xpathCtx);
    if (xpathObj == NULL) {
        fprintf(stderr, "Error: unable to evaluate XPath expression\n");
        xmlXPathFreeContext(xpathCtx);
        xmlFreeDoc(doc);
        return 1;
    }

    // Process the result
    if (xpathObj->nodesetval->nodeNr > 0) {
        for (int i = 0; i < xpathObj->nodesetval->nodeNr; i++) {
            xmlNodePtr node = xpathObj->nodesetval->nodeTab[i];
            printf("Node name: %s\n", node->name);
        }
    } else {
        printf("No matching nodes found\n");
    }

    // Clean up
    xmlXPathFreeObject(xpathObj);
    xmlXPathFreeContext(xpathCtx);
    xmlFreeDoc(doc);

    return 0;
}
```

